def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water >= 1:
            base = DAILY_SALARY * 0.6
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_aggressive += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22
    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if supply_tight:
        danger += 1

    if danger >= 5:
        target = max(DAILY_SALARY * 1.2, highest_prev + 2.0)
    elif danger >= 3:
        target = max(DAILY_SALARY * 0.92, avg_prev * 0.78 + 4.0)
    elif supply_tight and rich_aggressive >= 2:
        target = DAILY_SALARY * 0.48
    elif supply_loose and weak_opponents >= 1:
        target = DAILY_SALARY * 0.32
    else:
        target = DAILY_SALARY * 0.4

    if highest_prev >= 120:
        if danger <= 2:
            target = min(target, DAILY_SALARY * 0.42)
        else:
            target = max(target, DAILY_SALARY * 0.95)

    if day >= 8:
        if hp >= 6 and no_water == 0:
            target = min(target, DAILY_SALARY * 0.38)
        else:
            target = max(target, DAILY_SALARY * 0.8)

    if budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.7 + 5.0)

    bid = max(0.0, min(budget, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    strong_opponent_ids = ["Alex", "Eric"]

    strong_opp_prev_bids = []
    for opp_id in strong_opponent_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            opp_data = opponents_status[opp_id]
            if opp_data.get('previous_trace'):
                prev_bid = opp_data['previous_trace'].get('bid')
                if prev_bid is not None:
                    strong_opp_prev_bids.append(prev_bid)

    highest_strong_opp_bid = 0
    if strong_opp_prev_bids:
        highest_strong_opp_bid = max(strong_opp_prev_bids)

    bid = DAILY_SALARY * 0.7

    if my_hp <= 2:
        if highest_strong_opp_bid > 0:
            bid = max(DAILY_SALARY * 0.9, highest_strong_opp_bid + 5.0)
        else:
            bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        if highest_strong_opp_bid > 0:
            bid = max(DAILY_SALARY * 0.8, highest_strong_opp_bid + 2.0)
        else:
            bid = DAILY_SALARY * 0.85
    else:
        if highest_strong_opp_bid > 0:
            bid = max(DAILY_SALARY * 0.6, highest_strong_opp_bid + 1.0)
        else:
            bid = DAILY_SALARY * 0.7

    bid = min(bid, my_budget)

    bid = max(1.0, bid)

    return bid
